"use client";
import { useEffect, useState } from "react";
import { explorerApi, type DatabaseTable, type TableDescription } from "@/lib/api/explorer";

export function DatabaseExplorer() {
  const [tables, setTables] = useState<DatabaseTable[]>([]); const [selected, setSelected] = useState<TableDescription | null>(null); const [query, setQuery] = useState(""); const [error, setError] = useState<string | null>(null);
  useEffect(() => { void explorerApi.tables().then((result) => setTables(result.tables)).catch(() => setError("Database schema is unavailable.")); }, []);
  const choose = async (name: string) => { try { setSelected(await explorerApi.table(name)); } catch { setError("Table details are unavailable."); } };
  const shown = tables.filter((table) => table.name.toLowerCase().includes(query.toLowerCase()));
  return <aside className="explorer-panel"><h2>Database <small>{tables.length} tables</small></h2><input aria-label="Search database schema" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search schema" />{error && <p>{error}</p>}<div className="schema-layout"><nav>{shown.map((table) => <button key={table.name} onClick={() => void choose(table.name)}>{table.name}</button>)}</nav>{selected && <section><h3>{selected.table.name}</h3><ul>{selected.columns.map((column) => <li key={column.name}><strong>{column.name}</strong> <span>{column.data_type}</span>{column.nullable ? "" : " · required"}</li>)}</ul>{selected.foreign_keys.length > 0 && <><h4>Relationships</h4><ul>{selected.foreign_keys.map((key, index) => <li key={index}>{key.column_name} → {key.referenced_table}.{key.referenced_column}</li>)}</ul></>}</section>}</div></aside>;
}
